const pracTimes = p => (/^\d{2}:\d{2}$/.test(String(p.start || '')) ? p.start + '–' + (/^\d{2}:\d{2}$/.test(String(p.end || '')) ? p.end : addMins(p.start, Number(p.minutes) || 60)) : '');
