const SHELVES = { builtin: 'Built-in', club: 'Club', mine: 'Mine' };
const LS_MINE = 'sm.mine.v1';
const MINE_BLANK = () => ({ drills: {}, dirty: {}, tpls: {}, tplDirty: {} });
let mine = MINE_BLANK(), mineUid = null;
const shelfState = {};            // 'club' | 'mine' -> 'synced' | 'refused'
