    pushAlert({ id: 'm:' + x.id, code: elseMsg[p].code, kind: 'msg', topic: elseMsg[p].kind === 'board' ? 'notice' : 'msg', urgent: x.urgent, title: x.title, body: x.body, hash: x.hash });
