document.addEventListener('keydown', e => { if (e.key === 'Escape') closeSheet(); });
/* Time boxes (m:ss) keep their colon. On a phone's number pad there is no colon
   key, so a deleted colon could not be typed back and the time stopped parsing.
   Instead the box holds digits only and draws the colon itself: the last two
   digits are seconds, so typing 2 3 1 0 reads 23:10. Backspace over the colon
   deletes the digit before it, which is what she meant. */
function clockFormat(value, caret) {
  const v = String(value || '');
  const before = v.slice(0, caret == null ? v.length : caret).replace(/\D/g, '').length;
  let d = v.replace(/\D/g, '').replace(/^0+(?=\d{3})/, '');
  if (!d) return { value: '', caret: 0 };
  const lost = v.replace(/\D/g, '').length - d.length; // leading zeros trimmed
  d = d.padStart(3, '0');
  const out = d.slice(0, -2) + ':' + d.slice(-2);
  // put the caret back after the same number of digits it was after
  let want = Math.max(0, before - lost) + (d.length - (v.replace(/\D/g, '').length - lost));
  let pos = 0, seen = 0;
  while (pos < out.length && seen < want) { if (out[pos] !== ':') seen++; pos++; }
  return { value: out, caret: pos };
}
document.addEventListener('keydown', e => {
  const t = e.target;
  if (!t || !t.dataset || t.dataset.clock == null || t.selectionStart !== t.selectionEnd) return;
  const i = t.selectionStart;
  if (e.key === 'Backspace' && t.value[i - 1] === ':') t.setSelectionRange(i - 1, i - 1);
  else if (e.key === 'Delete' && t.value[i] === ':') t.setSelectionRange(i + 1, i + 1);
});
document.addEventListener('input', e => {
  const t = e.target;
  if (!t || !t.dataset || t.dataset.clock == null) return;
  const r = clockFormat(t.value, t.selectionStart);
  if (r.value === t.value) return;
  t.value = r.value;
  try { t.setSelectionRange(r.caret, r.caret); } catch (_) { /* not focused */ }
});


/* ---------------- routing ---------------- */
/* Hash routing rather than real paths: GitHub Pages has no rewrites, so
   /admin/clubname would need a 404.html redirect hack. The hash gives the same
   readable hierarchy, real back and forward, and links that survive a reload. */
function uiToHash() {
  normView();
  const t = ui.teamId, m = ui.matchId;
  if (ui.view === 'game' && t && m) return `#/team/${t}/game/${m}/${ui.gameView}`;
  if (ui.view === 'formation' && t && ui.editFid === GAME_SHAPE && m) return `#/team/${t}/game/${m}/shape`;
  if (ui.view === 'formation' && t) return `#/team/${t}/shape/${ui.editFid}`;
  /* The Calendar is the person's, at an address of its own that names no team
     and no club, and says which calendars it shows, so a link, a reload and
     the back button bring back the same ones. */
  if (ui.view === 'calendar') return calSel() === 'club' && calSels().includes('mine') ? '#/calendar/all' : '#/calendar';
  if (['practice', 'roster', 'season'].includes(ui.view) && t) {
    const seg = { practice: 'practice', roster: 'squad', season: 'season' }[ui.view];
    return `#/team/${t}/${seg}`;
  }
  if (ui.view === 'people') return '#/club/people';
  if (ui.view === 'club') return '#/club';
  if (ui.view === 'admin') return '#/club/settings';
  if (ui.view === 'planner') return '#/club/planner';
  if (ui.view === 'regs') return '#/club/registrations';
  if (ui.view === 'mine') return '#/my-players';
  if (ui.view === 'inbox') return '#/messages';
  if (ui.view === 'notes') return '#/notifications';
  if (ui.view === 'thread' && ui.thread && ui.thread.cid) return `#/messages/with/${sdOther(ui.thread.cid)}`;
  if (ui.view === 'thread' && ui.thread) return `#/messages/${ui.thread.tid}/${ui.thread.fam}`;
  if (ui.view === 'setup') return '#/settings';
  if (ui.view === 'sessions') { const tb = (ui.sess || {}).tab; return '#/training' + (tb && tb !== 'list' && SESS_TABS[tb] ? '/' + tb : ''); }
  return '#/';
}

function hashToUi() {
  const p = decodeURIComponent(location.hash.replace(/^#\/?/, '')).split('/').filter(Boolean);
  if (!p.length) return false;
  /* #/club/schedule was the admins' Club schedule and #/club/calendar its next
     address (build 102): All teams on the Calendar. #/my-calendar is what My
     calendar's feed links back to. */
  if (p[0] === 'club' && (p[1] === 'calendar' || p[1] === 'schedule')) { ui.view = 'calendar'; ui.calSel = 'club'; return true; }
  if (p[0] === 'club') { ui.view = p[1] === 'settings' ? 'admin' : p[1] === 'people' ? 'people' : p[1] === 'planner' ? 'planner' : p[1] === 'registrations' ? 'regs' : 'club'; return true; }
  if (p[0] === 'my-players') { ui.view = 'mine'; return true; }
  if (p[0] === 'my-calendar') { ui.view = 'calendar'; ui.calSel = 'mine'; return true; }
  if (p[0] === 'calendar') { ui.view = 'calendar'; ui.calSel = p[1] === 'all' ? 'club' : 'mine'; return true; }
  if (p[0] === 'messages') {
    // with a colleague: the address names the other person, never the pair, so it reads the same from either side
    if (p[1] === 'with' && p[2] && me) { ui.view = 'thread'; ui.thread = { cid: sdId(me.uid, p[2]) }; return true; }
    if (p[1] && p[2] && state.teams[p[1]]) { ui.view = 'thread'; ui.thread = { tid: p[1], fam: p[2] }; return true; }
    ui.view = 'inbox'; return true;
  }
  if (p[0] === 'notifications') { ui.view = 'notes'; return true; }
  if (p[0] === 'settings') { ui.view = 'setup'; return true; }
  /* #/drill/{key} is a drill a coach sent. The screen stays where it was and
     the drill opens over it, once: the hash goes straight back to the screen's
     own, so Back doesn't open it again. */
  if (p[0] === 'drill' && p[1]) {
    // #/drill/{club tag}/{key}, or #/drill/{key} for a built-in drill, which opens in any club
    // first, so a switch to the link's own club can put the link back on the address
    try { history.replaceState(null, '', location.pathname + location.search + uiToHash()); } catch (e) { }
    if (p[2]) followDrillLink(p.slice(2).join('/'), '', p[1]); else followDrillLink(p[1]);
    return true;
  }
  /* #/training/fields is a tab; #/training/{id} is one session, from a calendar
     file or a message, opened once the screen has drawn. */
  if (p[0] === 'training') {
    ui.view = 'sessions';
    const u = sessUi();
    if (p[1] && SESS_TABS[p[1]]) u.tab = p[1];
    else { u.tab = 'list'; if (p[1]) u.go = p[1]; }
    return true;
  }
  if (p[0] === 'team' && p[1]) {
    if (!state.teams[p[1]]) return false;
    ui.teamId = p[1];
    if (p[2] === 'game' && p[3]) {
      if (!state.matches[p[3]]) return false;
      ui.matchId = p[3]; ui.view = 'game';
      if (p[4] === 'shape') { ui.view = 'formation'; ui.editFid = GAME_SHAPE; return true; }
      if (GAME_VIEWS.includes(p[4])) ui.gameView = p[4];
      return true;
    }
    if (p[2] === 'shape' && p[3]) { ui.editFid = p[3]; ui.view = 'formation'; return true; }
    /* A team's calendar is the person's Calendar with that team on it (alerts
       and calendar files link here); its games were a tab of their own, and
       are its Season now, and its settings ("planning") are on Squad. */
    if (p[2] === 'calendar') { calShowTeam(p[1]); return true; }
    const back = { games: 'season', practice: 'practice', squad: 'roster', season: 'season', planning: 'roster' }[p[2]];
    ui.view = back || 'season';
    return true;
  }
  return false;
}

let routing = false, booted = false;
/* pushState, not replaceState: every move needs its own history entry or the
   phone's back gesture walks straight out of the app instead of up a level. */
function syncHash() {
  if (typeof history === 'undefined' || !history.pushState) return;
  const want = uiToHash();
  if (location.hash === want) return;
  routing = true;
  const url = location.pathname + location.search + want;
  if (booted && !sheetPushed) history.pushState(null, '', url); else history.replaceState(null, '', url);
  sheetPushed = false;
  booted = true;
  setTimeout(() => { routing = false; }, 0);
}
const avEl = $('#avatar');
if (avEl) avEl.addEventListener('click', () => (me ? sheetAccount() : sheetSignIn()));
const csEl = $('#clubSwitch');
if (csEl) csEl.addEventListener('click', sheetClubSwitch);
const ibEl = $('#msgBtn');
if (ibEl) ibEl.addEventListener('click', () => { ui.view = 'inbox'; ui.thread = null; closeSheet(); render(); });
const blEl = $('#bellBtn');
if (blEl) blEl.addEventListener('click', () => { ui.view = 'notes'; ui.thread = null; closeSheet(); render(); });
const cbEl = $('#calBtn');
if (cbEl) cbEl.addEventListener('click', () => { ui.view = 'calendar'; ui.picked = null; closeSheet(); render(); toTop(); });
// a tab brought back to the front has now read what arrived while it was behind
if (typeof document !== 'undefined' && document.addEventListener)
  document.addEventListener('visibilitychange', () => { if (!document.hidden && (ui.view === 'inbox' || ui.view === 'thread')) render(); });

if (typeof window !== 'undefined' && window.addEventListener) {
  const backOrForward = () => {
    if (sheetIgnorePop) { sheetIgnorePop = false; return; }
    // back with a sheet open closes the sheet, nothing else
    if (sheetPushed && !$('#sheet').hidden) { sheetPushed = false; $('#sheet').hidden = true; $('#scrim').hidden = true; return; }
    sheetPushed = false;
    if (routing) return;
    const want = uiToHash();
    if (location.hash === want) return;
    if (hashToUi()) { routing = true; render(); setTimeout(() => { routing = false; }, 0); }
  };
  window.addEventListener('popstate', backOrForward);
  window.addEventListener('hashchange', backOrForward);
}

/* ---------------- boot ---------------- */
captureInvite();
captureJoin();
captureReg();
captureOpen();
pushLoad();
loadLocal();
/* Provisional, so an offline device renders for the person who was using it
   rather than sitting on a lock screen. onAuthStateChanged overwrites it either
   way a moment later, and a sign-out has already cleared it. */
me = cachedMe();
copyCheck();
hashToUi();     // a shared link wins over whatever was last open
render();
pushListen();
(async () => { await initAuth(); await initSync(); })();
